// TOCHICD legend: fetched from tochicd_legend.json (generated by the pipeline from
// neoreef.common.landuse_codes). Nothing here is hand-copied from Python.

const DEFAULT_ENTRY = { code: -1, name_en: "Unknown", name_ja: "不明", color: "#CCCCCC", extrude_h: 5 };

export async function loadLegend(url) {
  const legend = { entries: [], byCode: new Map(), get: (code) => legend.byCode.get(Number(code)) ?? DEFAULT_ENTRY };
  if (!url) return legend;
  try {
    const resp = await fetch(url, { cache: "no-cache" });
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const data = await resp.json();
    legend.entries = data.entries ?? [];
    legend.entries.forEach(e => legend.byCode.set(Number(e.code), e));
  } catch (e) {
    console.warn("Legend unavailable, land-use colours fall back to GeoJSON properties:", e);
  }
  return legend;
}

// Renders rows for the codes in `activeCodes` (a Set) and hides the panel when empty.
export function buildLegend(legend, activeCodes, { panelId = "legend", itemsId = "legend-items" } = {}) {
  const panel = document.getElementById(panelId);
  const items = document.getElementById(itemsId);
  if (!panel || !items) return;
  items.innerHTML = "";
  for (const entry of legend.entries) {
    if (!activeCodes.has(Number(entry.code))) continue;
    const row = document.createElement("div");
    row.className = "legend-row";
    const swatch = document.createElement("div");
    swatch.className = "legend-swatch";
    swatch.style.background = entry.color;
    const lbl = document.createElement("span");
    lbl.textContent = entry.name_en;
    lbl.title = entry.name_ja;
    row.append(swatch, lbl);
    items.appendChild(row);
  }
  panel.style.display = items.children.length > 0 ? "block" : "none";
}
